import logging
from threading import Lock
from . import manual_probe
import math
KELVIN_TO_CELSIUS = -273.15

class TemperatureProbe:

    def __init__(self, config):
        self.name = config.get_name()
        self.printer = config.get_printer()
        self.reactor = self.printer.get_reactor()
        self.gcode = self.printer.lookup_object("gcode")
        self.speed = config.getfloat("speed", None, above=0.0)
        self.horizontal_move_z = config.getfloat("horizontal_move_z",
          2.0, above=0.0)
        self.resting_z = config.getfloat("resting_z", 0.4, above=0.0)
        self.zero_auto_probe = config.getboolean("zero_auto_probe", False)
        self.heater = None
        self.heater_choice = config.get("heater_choice", None)
        if self.heater_choice is None:
            smooth_time = config.getfloat("smooth_time", 2.0, above=0.0)
            self.inv_smooth_time = 1.0 / smooth_time
            self.min_temp = config.getfloat("min_temp",
              KELVIN_TO_CELSIUS, minval=KELVIN_TO_CELSIUS)
            self.max_temp = config.getfloat("max_temp",
              99999999.9, above=(self.min_temp))
            pheaters = self.printer.load_object(config, "heaters")
            self.sensor = pheaters.setup_sensor(config)
            self.sensor.setup_minmax(self.min_temp, self.max_temp)
            self.sensor.setup_callback(self._temp_callback)
            pheaters.register_sensor(config, self)
            self.temp_lock = Lock()
            self.last_temp_read_time = 0.0
        else:
            self.reactor.register_timer(self._temp_period_callback, self.reactor.NOW)
        self.smoothed_temp = 0.0
        self.measured_min = 99999999.0
        self.measured_max = 0.0
        self.cal_helper = None
        self.lift_speed = 5.0
        self.probe_speed = 5.0
        self.next_auto_temp = 99999999.0
        self.target_temp = 0
        self.expected_count = 0
        self.sample_count = 0
        self.in_calibration = False
        self.step = 2.0
        self.last_zero_pos = None
        self.total_expansion = 0
        self.start_pos = []
        self.gcode.register_command("PROBE_DRIFT_CALIBRATE",
          (self.cmd_PROBE_DRIFT_CALIBRATE),
          desc=(self.cmd_PROBE_DRIFT_CALIBRATE_help))

    def register_calibration_helper(self, helper):
        self.cal_helper = helper

    def _temp_callback(self, read_time, temp):
        if not temp:
            return
        with self.temp_lock:
            time_diff = read_time - self.last_temp_read_time
            self.last_temp_read_time = read_time
            temp_diff = temp - self.smoothed_temp
            adj_time = min(time_diff * self.inv_smooth_time, 1.0)
            self.smoothed_temp += temp_diff * adj_time
            self.measured_min = min(self.measured_min, self.smoothed_temp)
            self.measured_max = max(self.measured_max, self.smoothed_temp)
            st = self.smoothed_temp
            if self.in_calibration:
                if st >= self.next_auto_temp:
                    self.next_auto_temp = 99999999.0
                    self.printer.get_reactor().register_async_callback(lambda e, gc=self.gcode: gc.run_script("PROBE_DRIFT_NEXT"))

    def _temp_period_callback(self, eventtime):
        if self.heater is None:
            self.heater = self.printer.lookup_object(self.heater_choice).heater
        st = self.heater.smoothed_temp
        if not st:
            return eventtime + 0.2
        self.measured_min = min(self.measured_min, st)
        self.measured_max = max(self.measured_max, st)
        if self.in_calibration:
            if st >= self.next_auto_temp:
                self.next_auto_temp = 99999999.0
                self.printer.get_reactor().register_async_callback(lambda e, gc=self.gcode: gc.run_script("PROBE_DRIFT_NEXT"))
            return eventtime + 0.2

    def get_temp(self, eventtime=None):
        return (
         self.smoothed_temp if self.heater is None else self.heater.smoothed_temp, self.target_temp)

    def _collect_sample(self, kin_pos, tool_zero_z):
        probe = self._get_probe()
        (x_offset, y_offset, _) = probe.get_offsets()
        toolhead = self.printer.lookup_object("toolhead")
        cur_pos = toolhead.get_position()
        cur_pos[2] += self.horizontal_move_z
        toolhead.manual_move(cur_pos, self.lift_speed)
        cur_pos[0] -= x_offset
        cur_pos[1] -= y_offset
        move_speed = self.speed or self.probe_speed
        toolhead.manual_move(cur_pos, move_speed)
        speeds = (self.lift_speed, self.probe_speed, move_speed)
        return self.cal_helper.collect_sample(kin_pos, tool_zero_z, speeds)

    def _prepare_next_sample(self, last_temp, tool_zero_z):
        self.gcode.register_command("ABORT",
          (self.cmd_PROBE_DRIFT_ABORT), desc=(self.cmd_PROBE_DRIFT_ABORT_help))
        toolhead = self.printer.lookup_object("toolhead")
        cur_pos = toolhead.get_position()
        cur_pos[2] = tool_zero_z + self.resting_z
        toolhead.manual_move(cur_pos, self.probe_speed)
        cnt, exp_cnt = self.sample_count, self.expected_count
        self.next_auto_temp = last_temp + self.step
        self.gcode.respond_info("%s: collected sample %d/%d at temp %.2fC, next sample scheduled at temp %.2fC" % (
         self.name, cnt, exp_cnt, last_temp, self.next_auto_temp))
        if self.heater_choice == "extruder":
            self.gcode.run_script_from_command("M109 S" + str(math.ceil(self.next_auto_temp + 0.5)))
        elif self.heater_choice == "heater_bed":
            self.gcode.run_script_from_command("M190 S" + str(math.ceil(self.next_auto_temp + 0.5)))
        else:
            self.gcode.respond_info("%s: please manual control temp over %.2fC range" % (self.name, self.next_auto_temp))

    def _manual_probe_finalize(self, kin_pos):
        if kin_pos is None:
            self._finalize_drift_cal(False)
            return
        if self.last_zero_pos is not None:
            z_diff = self.last_zero_pos[2] - kin_pos[2]
            self.total_expansion += z_diff
            logging.info("Estimated Total Thermal Expansion: %.6f" % (
             self.total_expansion,))
        self.last_zero_pos = kin_pos
        toolhead = self.printer.lookup_object("toolhead")
        tool_zero_z = toolhead.get_position()[2]
        try:
            last_temp = self._collect_sample(kin_pos, tool_zero_z)
        except Exception:
            self._finalize_drift_cal(False)
            raise
        else:
            self.sample_count += 1
            if last_temp >= self.target_temp:
                self._finalize_drift_cal(True)
            else:
                try:
                    self._prepare_next_sample(last_temp, tool_zero_z)
                except Exception:
                    self._finalize_drift_cal(False)
                    raise

    def _finalize_drift_cal(self, success, msg=None):
        self.next_auto_temp = 99999999.0
        self.target_temp = 0
        self.expected_count = 0
        self.sample_count = 0
        self.step = 2.0
        self.in_calibration = False
        self.last_zero_pos = None
        self.total_expansion = 0
        self.start_pos = []
        self.gcode.register_command("ABORT", None)
        self.gcode.register_command("PROBE_DRIFT_NEXT", None)
        self.gcode.register_command("PROBE_DRIFT_COMPLETE", None)
        try:
            self.cal_helper.finish_calibration(success)
        except self.gcode.error as e:
            try:
                success = False
                msg = str(e)
            finally:
                e = None
                del e

        else:
            if not success:
                msg = msg or "%s: calibration aborted" % (self.name,)
                self.gcode.respond_info(msg)

    def _get_probe(self):
        probe = self.printer.lookup_object("probe")
        if probe is None:
            raise self.gcode.error("No probe configured")
        return probe

    def check_home(self):
        toolhead = self.printer.lookup_object("toolhead")
        kin = toolhead.get_kinematics()
        for i in (0, 1, 2):
            if kin.limits[i][0] > kin.limits[i][1]:
                raise self.printer.command_error("Must home axis first")

    cmd_PROBE_DRIFT_CALIBRATE_help = "Calibrate probe temperature drift compensation"

    def cmd_PROBE_DRIFT_CALIBRATE(self, gcmd):
        self.check_home()
        if self.cal_helper is None:
            raise gcmd.error("No calibration helper registered for [%s]" % (
             self.name,))
        probe = self._get_probe()
        manual_probe.verify_no_manual_probe(self.printer)
        if self.in_calibration:
            raise gcmd.error("Already in probe drift calibration. Use PROBE_DRIFT_COMPLETE or ABORT to exit.")
        cur_temp = self.get_temp()[0]
        target_temp = gcmd.get_float("TARGET", above=cur_temp)
        step = gcmd.get_float("STEP", 2.0, minval=1.0)
        expected_count = int((target_temp - cur_temp) / self.step + 0.5)
        if expected_count < 3:
            raise gcmd.error("Invalid STEP and/or TARGET parameters resulted in too few expected samples: %d" % (
             expected_count,))
        try:
            self.gcode.register_command("PROBE_DRIFT_NEXT",
              (self.cmd_PROBE_DRIFT_NEXT), desc=(self.cmd_PROBE_DRIFT_NEXT_help))
            self.gcode.register_command("PROBE_DRIFT_COMPLETE",
              (self.cmd_PROBE_DRIFT_COMPLETE), desc=(self.cmd_PROBE_DRIFT_NEXT_help))
        except self.printer.config_error:
            raise gcmd.error("Auxiliary Probe Drift Commands already registered. Use PROBE_DRIFT_COMPLETE or ABORT to exit.")
        else:
            self.in_calibration = True
            self.cal_helper.start_calibration()
            self.target_temp = target_temp
            self.step = step
            self.sample_count = 0
            self.expected_count = expected_count
            toolhead = self.printer.lookup_object("toolhead")
            self.start_pos = toolhead.get_position()[:2]
            self.lift_speed = probe.get_lift_speed(gcmd)
            self.probe_speed = probe.get_probe_speed(gcmd)
            if self.zero_auto_probe is not None:
                multi_prober = self.printer.lookup_object("creality_multi_probe")
                if multi_prober is None:
                    raise gcmd.error("Config object 'creality_multi_probe' must be specified")
                kin_pos = multi_prober.probe("G28 Z")
                self._manual_probe_finalize(kin_pos)
            else:
                manual_probe.ManualProbeHelper(self.printer, gcmd, self._manual_probe_finalize)

    cmd_PROBE_DRIFT_NEXT_help = "Sample next probe drift temperature"

    def cmd_PROBE_DRIFT_NEXT(self, gcmd):
        manual_probe.verify_no_manual_probe(self.printer)
        self.next_auto_temp = 99999999.0
        toolhead = self.printer.lookup_object("toolhead")
        curpos = toolhead.get_position()
        start_z = curpos[2]
        move_speed = self.speed or self.probe_speed
        curpos[2] += self.horizontal_move_z
        toolhead.manual_move(curpos, self.lift_speed)
        curpos[0] = self.start_pos[0]
        curpos[1] = self.start_pos[1]
        toolhead.manual_move(curpos, move_speed)
        curpos[2] = start_z
        toolhead.manual_move(curpos, self.probe_speed)
        self.gcode.register_command("ABORT", None)
        if self.zero_auto_probe is not None:
            multi_prober = self.printer.lookup_object("creality_multi_probe")
            if multi_prober is None:
                raise gcmd.error("Config object 'creality_multi_probe' must be specified")
            kin_pos = multi_prober.probe("G28 Z")
            self._manual_probe_finalize(kin_pos)
        else:
            manual_probe.ManualProbeHelper(self.printer, gcmd, self._manual_probe_finalize)

    cmd_PROBE_DRIFT_COMPLETE_help = "Finish Probe Drift Calibration"

    def cmd_PROBE_DRIFT_COMPLETE(self, gcmd):
        manual_probe.verify_no_manual_probe(self.printer)
        self._finalize_drift_cal(self.sample_count >= 3)

    cmd_PROBE_DRIFT_ABORT_help = "Abort Probe Drift Calibration"

    def cmd_PROBE_DRIFT_ABORT(self, gcmd):
        self._finalize_drift_cal(False)

    def is_in_calibration(self):
        return self.in_calibration

    def get_status(self, eventtime=None):
        return {'temperature':self.get_temp()[0], 
         'measured_min_temp':round(self.measured_min, 2), 
         'measured_max_temp':round(self.measured_max, 2), 
         'in_calibration':self.in_calibration, 
         'estimated_expansion':self.total_expansion}

    def stats(self, eventtime):
        return (
         False, "%s: temp=%.1f" % (self.name, self.get_temp()[0]))


def load_config(config):
    return TemperatureProbe(config)

